def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 4:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = sum(1 for x in op if x == 'C')
    opp_rate = opp_c / n
    my_d = sum(1 for x in my if x == 'D')
    my_rate = my_d / n

    ret = 0
    forg = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if op[i + 1] == 'D':
                ret += 1
            else:
                forg += 1
    total = ret + forg
    ret_rate = ret / total if total > 0 else 0.5

    last_op = op[-1]
    last_me = my[-1]

    if n >= 95:
        if opp_rate > 0.9 and ret_rate < 0.3:
            return 'D'
        if opp_rate < 0.2:
            return 'D'
        if ret_rate > 0.5:
            if last_op == 'D':
                return 'D'
            return 'C'

    if opp_rate < 0.2:
        if n < 90 and rng.random() < 0.05:
            return 'C'
        return 'D'

    if opp_rate > 0.8:
        if ret_rate > 0.5:
            if n < 20 and my_d == 0 and n > 5:
                if rng.random() < 0.1:
                    return 'D'
            return 'C'
        else:
            if n < 20:
                if my_d == 0 and n > 5 and rng.random() < 0.1:
                    return 'D'
                return 'C'
            else:
                recent_my_d = sum(1 for x in my[-10:] if x == 'D')
                if recent_my_d == 0:
                    if my_d >= 3 and ret_rate < 0.1:
                        return 'D'
                    prob = 0.4 if ret_rate < 0.1 else 0.2
                    if rng.random() < prob:
                        return 'D'
                return 'C'

    if last_op == 'D':
        if last_me == 'D':
            if opp_rate > 0.5:
                return 'C'
            return 'D' if rng.random() < 0.3 else 'C'
        else:
            if ret_rate > 0.5 and my_rate < 0.3:
                if len(op) >= 2 and op[-2] == 'D':
                    return 'D'
                return 'C'
            return 'D'
    else:
        if last_me == 'D':
            if ret_rate < 0.3 and opp_rate > 0.6 and n < 95:
                if rng.random() < 0.5:
                    return 'D'
            return 'C'
        else:
            if opp_rate > 0.6 and ret_rate < 0.2 and n < 90:
                recent_my_d = sum(1 for x in my[-10:] if x == 'D')
                if recent_my_d == 0 and rng.random() < 0.1:
                    return 'D'
            return 'C'
